## TypeScript类型系统

### 基础类型
```ts
let num: number = 42;
let str: string = 'hello';
let bool: boolean = true;
let arr: number[] = [1, 2, 3];
let tuple: [string, number] = ['age', 25];
let nul: null = null;
let undef: undefined = undefined;
let sym: symbol = Symbol('id');
let big: bigint = 100n;
```

### 特殊类型
- **any**：任意类型，关闭类型检查
- **unknown**：类型安全的any，使用前必须收窄
- **never**：永远不会有值的类型（异常、死循环、穷尽检查）
- **void**：函数无返回值
- **object**：非原始类型

### 联合与交叉
```ts
type Union = string | number;  // 取并集
type Intersection = { a: string } & { b: number }; // 取交集
```

### 类型收窄（Narrowing）
```ts
function process(val: string | number) {
  if (typeof val === 'string') {
    val.toUpperCase(); // 收窄为string
  } else {
    val.toFixed(2); // 收窄为number
  }
}
```

收窄方式：typeof、instanceof、in、字面量比较、真值检查、自定义类型守卫。

// 联合类型与类型收窄
type Shape = 'circle' | 'square' | 'triangle';

interface Circle { kind: 'circle'; radius: number; }
interface Square { kind: 'square'; side: number; }
type ShapeObj = Circle | Square;

// 可辨识联合（Discriminated Union）
function area(shape: ShapeObj): number {
  switch (shape.kind) {
    case 'circle':
      return Math.PI * shape.radius ** 2;
    case 'square':
      return shape.side ** 2;
  }
}

// never的穷尽检查
type Color = 'red' | 'green' | 'blue';

function getColorCode(color: Color): string {
  switch (color) {
    case 'red': return '#FF0000';
    case 'green': return '#00FF00';
    case 'blue': return '#0000FF';
    default:
      const _exhaustive: never = color; // 如果漏掉分支会报错
      return _exhaustive;
  }
}

// unknown vs any
let value: unknown = 'hello';
// value.toUpperCase(); // 错误！unknown必须先收窄
if (typeof value === 'string') {
  value.toUpperCase(); // OK
}

let anything: any = 'hello';
anything.toUpperCase(); // OK，但不安全

// 自定义类型守卫
function isString(val: unknown): val is string {
  return typeof val === 'string';
}

function process2(val: unknown) {
  if (isString(val)) {
    val.toUpperCase(); // 收窄为string
  }
}

// const断言
type Direction = 'up' | 'down' | 'left' | 'right';
const dir = 'up' as const; // 类型为 'up'
const arr = [1, 2, 3] as const; // readonly [1, 2, 3]
